import sys
from collections import deque

def solve():
    T = int(sys.stdin.readline())
    for _ in range(T):
        N, M, K = map(int, sys.stdin.readline().split())
        if N == 1 and M == 1:
            print(0)
            continue
        total_cells = (N-1)*(M-1)
        if K <= total_cells:
            print(1)
        else:
            print(K // total_cells + (1 if K % total_cells != 0 else 0))

solve()
